#!/usr/bin/env python3
"""Build an explicit, manually specified purposive evidence ledger and descriptive tables."""
import csv,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]; DATA=ROOT/'revision/data'
def write(name,rows):
 with (DATA/name).open('w',newline='',encoding='utf-8') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
