# Recorded targeted update, 21 October 2026 (queries in search_update_2026-10-21.json); same tuple layout.
UPDATE=[
('DeJongDeHaro2026', '10.1007/s11229-026-05503-2', 'technology-and-society framing: concept of technological understanding', 'dejongdeharo2026_web.txt; Abstract; Sect. 3.1 (definition, CTU, CITA); Sect. 3.2 (three logical options); Sect. 3.3; Sect. 4 Conclusion', "Defines technological understanding as the ability to use a technological artefact to realise a practical aim (broadly including design and conceptual and actual use), specifies maximal/minimal/via-media options ('conceptualising', operation, 'design for use') and develops the design context, using superconducting quantum computers as an example of incomplete technological understanding.", "A philosophical account focused on design; it does not use a 'societal embedding' category, does not address school education or public reasoning, and contains no empirical data."),
('DeJong2026', '10.1007/s11569-026-00501-7', 'technology-and-society framing: functional understanding as epistemic condition for ethical debate', "dejong2026_web.txt; Abstract; 'Understanding as a Critical Enabler of Ethical Enquiry'; 'Three Types of Technological Understanding' (design, operation, innovation; functional understanding para); 'Understanding Functions rather than Physics'; Conclusion", 'Argues that meaningful ethical discussion of quantum technologies depends first on functional understanding (what a technology can and cannot be expected to do), that physics-first explanations are neither sufficient nor always necessary for this, and that impact debate should proceed cautiously where capabilities are uncertain.', 'A conceptual argument without empirical testing; it does not study students or curricula and does not claim that functional understanding settles ethical questions.'),
('Greinert2023', '10.1103/physrevphyseducres.19.010137', 'workforce-framework provenance of the item pool', "greinert2023_web.txt; Abstract; Sec. I (R1, R2); Table II; Sec. IV.4; Sec. V (version 1.0, Fig. 6 caption); Table VIII 'Soft skills, social aspects'; Fig. 9; Table X (S15, Q2); refs [19], [21]", 'Reports a three-round survey (188 responses, March 2020 to May 2021) of mainly academic experts that fed the European Competence Framework for Quantum Technologies, whose stated aim is mapping competences for the future quantum workforce; version 1.0 (May 2021, eight main domains) is described as mainly content-specific.', 'Expert-survey evidence about workforce requirements with a strong academic perspective; it does not establish what upper-secondary students or citizens need for public reasoning.'),
('GreinertMuller2021', '10.5281/zenodo.6834599', 'source framework (CFQT v1.0) from which the thesis item pool was adapted', "greinertmuller2021_web.txt; p. 2 overview (fields 1-8, subfields 8.1-8.9); p. 3 'How to use'; p. 10 field 7.1; p. 11 field 8 detail", "Version 1.0 (May 2021; Zenodo issued 7 Sept 2021) is compiled to facilitate planning of QT education and training, has eight numbered fields, and field 8 'Practical and soft skills' lists 8.3 Management and leadership (incl. 'Economic impact of QT') and 8.8 'Research ethics, responsible research and innovation' (heading only, no subtopics).", 'Shows which headings the framework lists; it does not show which version or items the thesis actually used, nor that the framework addresses public or civic reasoning beyond these headings.'),
('GreinertMuller2024', '10.2759/389764', 'later official EU edition of CFQT (v2.5) for comparison of how societal/ethical content developed', 'greinertmuller2024_web.txt; op.europa.eu record abstract and metadata; PDF p. 1 cover; p. 2 imprint; p. 3 overview; PDF p. 14 (printed p. 13) domain 8; PDF p. 18 proficiency area III A1/A2', "The EU-published Version 2.5 (April 2024; ISBN 978-92-68-16473-0) describes CFQT as a taxonomy of knowledge and skills needed for involvement in the QT industry, with domain 8 'Valorisation' containing 8.3 Impact (economic, societal and environmental) and 8.4 Responsibility and awareness (responsibility, ethics; public communication; education).", 'A 2024 edition that post-dates the 2021 thesis, so it cannot be the source of the thesis item pool; a newer edition (v3.0, 2025, doi 10.2759/8917117) exists.'),
('Inglesant2021', '10.1080/09537325.2021.1988557', 'technology-and-society framing: responsible innovation and visions of quantum computing', "inglesant2021_web.txt; Abstract; 'Visions of Quantum Computing'; 'Quantum supremacy' para 2; 'Conclusions' paras 4-5", "From responsible-innovation work in a UK quantum computing hub, the authors argue that great uncertainty surrounds timescales and applications, that 'quantum supremacy' concerns speed-ups on specialised problems not expected to replace classical computing in general, and that examining visions and sociotechnical imaginaries helps anticipate societal implications.", 'A reflective account from one UK programme; it does not evaluate education or measure public understanding.'),
('TenHolter2023', '10.1080/09537325.2021.1988070', 'technology-and-society framing: public engagement, hype management and schooling gap', 'tenholter2023_web.txt; Abstract; 3.1 (QML case study); 4.1 Finding 1; 4.4 Finding 4; 5.2 R2; 6 Conclusions', "Reports UK NQIT hub interviews, workshops and a public dialogue in which the public showed familiarity with 'quantum' but little practical knowledge, researchers stressed avoiding hype, and several interviewees wanted earlier quantum education, noting its absence from the National Curriculum.", 'Qualitative evidence from one national research programme; interviewee views on curricula are not an analysis of school curricula or of student learning.'),
('Seskir2023', '10.1088/2058-9565/acb6ae', "technology-and-society framing: democratic participation and the 'incomprehensible' narrative", 'seskir2023_web.txt; Abstract; Sect. 1 para 4; Sect. 2 (front end); Sect. 3.2.2; Sect. 4.3; Sect. 5', 'Argues that current QT democratization efforts (mainly cloud access promoted by companies) are necessary but not sufficient, that access does not guarantee agency, and that the narrative that quantum mechanics is incomprehensible blurs the science-pseudoscience line and makes public deliberation about QT impossible.', 'A conceptual analysis that deliberately omits ethics and presents no empirical data on learners or the public.'),
('SotoSanfiel2025', '10.1057/s41599-025-05200-4', 'hype in quantum science communication (target-journal source)', "sotosanfiel2025_web.txt; Abstract p. 1; Methods 'Participants and procedure' p. 4; Conclusions p. 9; Limitations pp. 9-10", 'In five focus groups with 24 quantum physicists at one research centre in Abu Dhabi, participants acknowledged their own role in hype and its strategic use for funding, and saw mainly negative potential consequences including erosion of public trust and the spread of pseudoscience.', 'Qualitative self-reports from a small, single-centre, 92% male sample with possible social-desirability bias; it does not measure hype in media or its effect on audiences or students.'),
('Brang2025', '10.1140/epjqt/s40507-025-00403-9', 'evaluating quantum-terminology claims; nature-of-science reasoning', 'brang2025_web.txt; Abstract; 1 Introduction (Bondani et al. [13]); 1.1; 2.1; 2.3; 3 Results; 4.1; 5 Limitations; 6 Conclusion', "In an exploratory vignette study, most of 28 German pre-service physics teachers identified scientific errors and misuse of quantum jargon in a 'quantum healing' text, but only 13 raised nature-of-science critiques such as empirical basis or source evaluation.", 'Small, exploratory, hypothetical-vignette study of pre-service teachers with quantum-physics training; it says nothing directly about upper-secondary students or the public and the vignette framing may have cued scepticism.'),
('ANSSI2024', '', 'official security assessment constraining quantum-secure communication claims', 'anssi2024_web.txt; ANSSI publication page; PDF p. 1 Executive summary; p. 2-3 Sec. 2; p. 3-4 Sec. 3; p. 4 Sec. 4; p. 5 Sec. 5 Conclusion', "Four European security agencies conclude that QKD is currently usable only in niche cases, is not yet sufficiently mature from a security perspective, requires classically authenticated channels, cannot deliver 'absolute' security in actual implementations, and that migration to post-quantum cryptography (with symmetric keying) should be the priority.", 'A policy position of four agencies as of early 2024 on QKD for key establishment; it does not assess other quantum communication uses and is not a peer-reviewed technical evaluation.'),
('NCSC2025', '', 'current official UK position on QKD and quantum networking', "ncsc2025_web.txt; Web page: intro; 'Quantum Key Distribution' paras 1-2 and 'For these reasons' list; 'Quantum networking'; footer 'PUBLISHED 5 August 2025, VERSION 1.0'", "The NCSC's updated analysis (5 August 2025) states that QKD does not provide authentication and must be combined with other cryptographic services, will not be supported for government or military applications, should not be solely relied on in other sectors, and that post-quantum cryptography is the primary/best mitigation.", 'A UK agency position written for cyber security professionals; it does not assess educational use and is not peer reviewed.'),
('Preskill2018', '10.22331/q-2018-08-06-79', 'computational-advantage claims are problem-specific and benchmarked against a moving classical target', 'preskill2018_web.txt; Abstract p. 1; Sec. 1 p. 1; Sec. 3.1 p. 3; Sec. 6 pp. 6-7; Sec. 6.6 pp. 10-11', 'Preskill states that the power of a quantum computer is not unlimited (hard NP-hard instances are not expected to be solved efficiently), that a speedup means outperforming the best classical hardware and algorithm for the same task, that classical methods are a moving target, that usefulness of the task matters, and that near-term commercial potential is uncertain.', 'An expert perspective from 2018 on NISQ-era prospects; it does not provide current benchmarks and does not address education or public reasoning.'),
('Feinstein2011', '10.1002/sce.20414', "origin of the 'competent outsider' aim of science literacy", 'feinstein2011_web.txt; Abstract (Crossref)', 'Feinstein argues that the usefulness of science literacy has become a rhetorical claim, that useful science literacy must connect to real uses of science in daily life (public engagement with science), and that it can be salvaged by helping students become competent outsiders with respect to science.', 'Only the abstract was verified; it is a conceptual essay, not empirical evidence, and does not concern quantum topics.')]
records=json.loads((DATA/'literature_records.json').read_text()); bydoi={r['doi']:r for r in records if r['doi']}
rows=[]
for key,doi,role,locator,support,boundary in SOURCES:
 r=bydoi.get(doi,{})
 rows.append(dict(citation_key=key,doi=doi,legacy_record_id=r.get('record_id','supplementary_identification'),role=role,
  selection='included_purposively',access='full_text_or_official_document',source_locator=locator,support=support,inference_boundary=boundary,
  reason='Provides a distinct evidence role required by the three research questions',stage='original_2026-10-12'))
rows.append(dict(citation_key='Oikonomou2026',doi='10.1007/s44217-026-01941-9',legacy_record_id='supplementary_identification',role='teacher readiness candidate',selection='not_used_in_synthesis',access='abstract_and_incomplete_indexed_body',source_locator='oikonomou2026_web.txt',support='',inference_boundary='Insufficient methods/results retrieved for appraisal',reason='Access limitation; not a quality judgement',stage='original_2026-10-12'))
for key,doi,role,locator,support,boundary in UPDATE:
 r=bydoi.get(doi,{}) if doi else {}
 rows.append(dict(citation_key=key,doi=doi,legacy_record_id=r.get('record_id','supplementary_identification'),role=role,
  selection='included_targeted_update',access='full_text_or_official_document',source_locator=locator,support=support,inference_boundary=boundary,
  reason='Recorded targeted update; see search_update_2026-10-21.json',stage='update_2026-10-21'))
write('fulltext_decisions.csv',rows)
selected={r['legacy_record_id'] for r in rows if r['selection']=='included_purposively'}
titles=[]
for r in records:
 if r['discovery_class']=='A_quantum_secondary':
  titles.append(dict(record_id=r['record_id'],doi=r['doi'],title=r['title'],review_scope='title-level purposive triage',decision='selected_for_evidence_role' if r['record_id'] in selected else 'not_taken_forward',reason='Specific evidence role retained in fulltext_decisions.csv' if r['record_id'] in selected else 'Not selected for this purposive synthesis; no full-text quality or eligibility judgement'))
write('title_triage.csv',titles)
ratings=list(csv.DictReader((DATA/'curriculum_ratings.csv').open()))
for r in ratings:r['shaded_selected']=r['word_row_shading']=='F2F2F2'
summary=[]
for k in range(1,9):
 a=[r for r in ratings if int(r['domain_id'])==k]
 summary.append(dict(domain_id=k,rated_items=len(a),numeric_cutoff_items=sum(r['meets_reported_numeric_cutoff']=='true' for r in a),shaded_selected_items=sum(r['shaded_selected'] for r in a),favorable_min_percent=min(float(r['favorable_percent']) for r in a),favorable_max_percent=max(float(r['favorable_percent']) for r in a)))
write('curriculum_domain_summary.csv',summary)
write('threshold_sensitivity.csv',[dict(range_fraction=c,cutoff=92+c*(156-92),items_meeting_cutoff=sum(float(r['reported_expertise_weighted_score'])>=92+c*64 for r in ratings),interpretation='Sensitivity of the thesis-reported scores; separate workbook audit reproduces stored scores and reports raw-label recoding') for c in [.35,.45,.55]])
s=list(csv.DictReader((DATA/'student_distributions.csv').open()));exitrows=[]
for k in range(1,9):
 a=[r for r in s if int(r['domain_id'])==k and r['occasion']=='after' and r['source_kind']=='table'];n=sum(int(r['count']) for r in a if r['level'] in ['sufficient','high'])
 exitrows.append(dict(domain_id=k,domain=a[0]['domain'],sufficient_or_high_n=n,denominator=45,percent=round(n/45*100,1),baseline_conflict=k in [3,4],interpretation='Exit classification only; not a gain estimate'))
write('student_exit_summary.csv',exitrows)
print(json.dumps(dict(included_sources=len(SOURCES),update_sources=len(UPDATE),educational_sources=9,title_triage=len(titles),shaded_selected=sum(r['shaded_selected'] for r in ratings),numeric_selected=sum(r['meets_reported_numeric_cutoff']=='true' for r in ratings)),indent=2))
